import{_ as l,a0 as t,w as d,s as o,I as i,x as a,a1 as n,A as p,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"三种在 Linux 上创建或扩展交换分区的简单方法 | LCTT x X-CMD","titleTemplate":false,"description":"三种在 Linux 上创建或扩展交换分区的简单方法 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三种在 Linux 上创建或扩展交换分区的简单方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三种在 Linux 上创建或扩展交换分区的简单方法 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux","title":"三种在 Linux 上创建或扩展交换分区的简单方法","tag":"201707","desc":""},"relativePath":"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux.md","filePath":"[post].md"}'),h={name:"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux.md"};function g(c,s,k,b,u,f){const e=t("Link");return d(),o("div",null,[s[18]||(s[18]=i("h1",{id:"三种在-linux-上创建或扩展交换分区的简单方法",tabindex:"-1"},[a("三种在 Linux 上创建或扩展交换分区的简单方法 "),i("a",{class:"header-anchor",href:"#三种在-linux-上创建或扩展交换分区的简单方法","aria-label":"Permalink to “三种在 Linux 上创建或扩展交换分区的简单方法”"},"​")],-1)),s[19]||(s[19]=i("p",null,"用户可以在任何 Linux\b 操作系统的安装过程中或者是其它必要的时候创建交换空间。如果你在安装 Linux 的时候忘记了创建或是你想要再增加交换分区的空间，你随时都可以再创建或增加。",-1)),s[20]||(s[20]=i("p",null,"有时候在你安装后摇升级 RAM 的时候需要增加一点交换分区的空间，比如你要将你的系统的 RAM 从 1GB 升级到 2GB 你，那么你就不得不将你的交换分区空间也升级一下（从 2GB 到 4GB），这是因为它使用的容量是物理 RAM 的双倍容量。（LCTT 译注：其实这里是个误区，交换分区不一定非得是双倍的物理内存容量，只是惯例如此。事实上，如果你的物理内存足够的话，你完全可以不用交换分区——在这里的情形下，或许你增加了物理内存，就没必要增加交换分区大小了。）",-1)),s[21]||(s[21]=i("p",null,"\b\b交换空间是当物理内存（RAM 随机存取存储器）的用量已满时，被保留用作虚拟内存的磁盘上的空间。 如果系统在 RAM 满载时需要更多的内存资源，内存中的非活动页面将被移动到交换空间，这样可以帮助系统运行应用程序更多的时间，但不应\b该把它当做 RAM 的扩展。",-1)),s[22]||(s[22]=i("p",null,"建议你创建一个专用的交换分区，但是如果你没有可用的分区，那么可以使用交换文件，或交换分区和交换文件的组合。 交换空间通常建议用户至少 4 GB，用户也可以根据自己的要求和环境创建交换空间。",-1)),s[23]||(s[23]=i("p",null,"我发现大部分 VM 和 云服务器都没有交换分区，所以在这种情况下，我们可以使用以下三种方法创建，扩展或增加交换空间。",-1)),s[24]||(s[24]=i("h3",{id:"如何检测当前交换分区大小",tabindex:"-1"},[a("如何检测当前交换分区大小 "),i("a",{class:"header-anchor",href:"#如何检测当前交换分区大小","aria-label":"Permalink to “如何检测当前交换分区大小”"},"​")],-1)),i("p",null,[s[1]||(s[1]=a("通过 ",-1)),n(e,{href:"http://www.2daygeek.com/free-command-to-check-memory-usage-statistics-in-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("free",-1)])]),_:1}),s[2]||(s[2]=a(" & ",-1)),s[3]||(s[3]=i("code",null,"swapon",-1)),s[4]||(s[4]=a(" 命令来检测当前的交换分区空间的大小。",-1))]),s[25]||(s[25]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -h</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           2.0G        1.3G        139M         45M        483M        426M</span></span>
<span class="line"><span>Swap:          2.0G        655M        1.4G</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME      TYPE      SIZE   USED PRIO</span></span>
<span class="line"><span>/dev/sda5 partition   2G 655.2M   -1</span></span></code></pre></div><p>上面的输出显示了\b当前的交换分区空间是 <code>2GB</code> 。</p><h3 id="方法-1-通过-fallocate-命令创建交换文件" tabindex="-1">方法 1 : 通过 fallocate 命令创建交换文件 <a class="header-anchor" href="#方法-1-通过-fallocate-命令创建交换文件" aria-label="Permalink to “方法 1 : 通过 fallocate 命令创建交换文件”">​</a></h3><p><code>fallocate</code> 程序是立即创建预分配大小的文件的最佳方法。</p><p>下面这个命令会创建一个 1GB 大小\b的 <code>/swapfile</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fallocate -l 1G /swapfile</span></span></code></pre></div><p>检查\b一下创建的文件的大小是否正确。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh /swapfile</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 1.0G Jun  7 09:49 /swapfile</span></span></code></pre></div><p>将该文件的权限设置为 <code>600</code> 这样只有 root 用户可以\b访问这个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /swapfile</span></span></code></pre></div><p>通过\b运行以下的命令来将此文件\b转换为交换文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /swapfile</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 1024 MiB (1073737728 bytes)</span></span>
<span class="line"><span>no label, UUID=cda50e0e-41f3-49c7-af61-b8cb4a33a464</span></span></code></pre></div><p>通过运行以下的命令来使交换文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /swapfile</span></span></code></pre></div><p>将新创建的交换文件添加到 <code>fstab</code> 文件中，这样交换分区空间\b的修改即使在重启后也可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/swapfile  swap  swap  defaults  0 0</span></span></code></pre></div><p>检查一下新创建的交换文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME      TYPE       SIZE   USED PRIO</span></span>
<span class="line"><span>/dev/sda5 partition    2G 657.8M   -1</span></span>
<span class="line"><span>/swapfile file      1024M     0B   -2</span></span></code></pre></div><p>现在\b我可以看到一个新的  1GB 的 <code>/swapfile1</code> 文件了。重启系统以使新的交换文件生效。</p><h3 id="方法-2-通过-dd-命令来创建交换文件" tabindex="-1">方法 2 : 通过 dd 命令来创建交换文件 <a class="header-anchor" href="#方法-2-通过-dd-命令来创建交换文件" aria-label="Permalink to “方法 2 : 通过 dd 命令来创建交换文件”">​</a></h3><p><code>dd</code> 命令是另一个实用程序，可以帮助我们立即创建预分配大小的文件。</p><p>以下 dd 命令将创建 1GB 的 <code>/swapfile1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dd if=/dev/zero of=/swapfile1 bs=1G count=1</span></span>
<span class="line"><span>1+0 records in</span></span>
<span class="line"><span>1+0 records out</span></span>
<span class="line"><span>1073741824 bytes (1.1 GB, 1.0 GiB) copied, 16.6154 s, 64.6 MB/s</span></span></code></pre></div><p><strong>详解：</strong></p><ul><li><code>if=/dev/zero</code> 是输入文件，<code>/dev/zero</code> 是类 Unix 操作系统中的一个特殊文件，它提供从它读取的尽可能多的空字符（ASCII NUL，0x00）。</li><li><code>of=/swapfile1</code> \b设置输出文件。</li><li><code>bs=1G</code> 一次性读写的\b大小为 1GB</li><li><code>count=1</code> 仅复制一个输入块</li></ul><p>检查\b一下创建的文件的大小是否正确。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh /swapfile1</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 1.0G Jun  7 09:58 /swapfile1</span></span></code></pre></div><p>将该文件的权限设置为 <code>600</code> 这样只有 root 用户可以\b访问这个文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /swapfile1</span></span></code></pre></div><p>通过\b运行以下的命令来将此文件\b转换为交换文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /swapfile1</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 1024 MiB (1073737728 bytes)</span></span>
<span class="line"><span>no label, UUID=96def6d7-b2da-4954-aa72-aa32316ec993</span></span></code></pre></div><p>通过运行以下的命令来使交换文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /swapfile1</span></span></code></pre></div><p>将新创建的交换文件添加到 <code>fstab</code> 文件中，这样交换分区空间\b的修改即使在重启后也可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/swapfile1  swap  swap  defaults  0 0</span></span></code></pre></div><p>检查新创建的交换文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME       TYPE       SIZE USED PRIO</span></span>
<span class="line"><span>/dev/sda5  partition    2G 1.3G   -1</span></span>
<span class="line"><span>/swapfile  file      1024M   0B   -2</span></span>
<span class="line"><span>/swapfile1 file      1024M   0B   -3</span></span></code></pre></div><p>现在\b我可以看到一个新的  1GB 的 <code>/swapfile1</code> 了。重启系统以使新的交换文件生效。</p><h3 id="方法-3-通过硬盘分区来创建交换文件" tabindex="-1">方法 3 : 通过硬盘分区来创建\b交换文件 <a class="header-anchor" href="#方法-3-通过硬盘分区来创建交换文件" aria-label="Permalink to “方法 3 : 通过硬盘分区来创建\b交换文件”">​</a></h3><p>我们也推荐使用通过硬盘分区的方式来创建交换分区。</p><p>如果你已经在你的另一个硬盘上通过 <code>fdisk</code> 命令创建了一个新的分区，假设我们已经创建了一个叫做 <code>/dev/sda4</code> 的分区。</p><p>使用 <code>mkswap</code> 命令来将这个分区转换成交换\b分区。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/sda4</span></span></code></pre></div><p>通过\b运行以下命令来使交换文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /dev/sda4</span></span></code></pre></div><p>把新增的交换文件添加到 <code>fstab</code> 文件中，这样即使是重启了系统交换分区的\b修改也能生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda4  swap  swap  defaults  0 0</span></span></code></pre></div><p>检查新创建的交换文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME       TYPE       SIZE USED PRIO</span></span>
<span class="line"><span>/dev/sda5  partition    2G 1.3G   -1</span></span>
<span class="line"><span>/swapfile  file      1024M   0B   -2</span></span>
<span class="line"><span>/swapfile1 file      1024M   0B   -3</span></span>
<span class="line"><span>/dev/sda4  partition    1G   0B   -4</span></span></code></pre></div><p>我可以看到新的交换分区 1GB 的 <code>/dev/sda4</code>。重启系统就可以使用新的交换分区了。</p><hr>`,51)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"http://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/"},{default:p(()=>[...s[5]||(s[5]=[a("http://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),n(e,{href:"http://www.2daygeek.com/author/2daygeek/"},{default:p(()=>[...s[7]||(s[7]=[a("2DAYGEEK",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),n(e,{href:"https://github.com/chenxinlong"},{default:p(()=>[...s[8]||(s[8]=[a("chenxinlong",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const m=l(h,[["render",g]]);export{x as __pageData,m as default};
